import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'docs', 'profiling');
const combat = JSON.parse(readFileSync(join(dir, 'combat-profile.json'), 'utf8'));
const memory = JSON.parse(readFileSync(join(dir, 'memory-cycles.json'), 'utf8'));
const hardware = process.argv[2] ?? 'not provided';

const env = combat.environment;
const lines = [
  '# Performance profile',
  '',
  'Generated by `npm run perf:profile` (Playwright, production build served by `vite preview`) and summarised with `node scripts/profiling-report.mjs`.',
  'Raw data: [combat-profile.json](combat-profile.json) and [memory-cycles.json](memory-cycles.json).',
  '',
  '## Reference environment',
  '',
  '| Item | Value |',
  '| --- | --- |',
  `| Hardware | ${hardware} |`,
  `| Browser | ${env.userAgent} |`,
  `| WebGL renderer | ${env.webglRenderer} (${env.webglVendor}) |`,
  `| Logical CPUs reported | ${env.hardwareConcurrency} |`,
  `| Viewport | ${env.viewport.width} × ${env.viewport.height}, device pixel ratio ${env.devicePixelRatio} |`,
  `| Build | \`npm run build\` (Vite production build) |`,
  '',
  '## Three-minute combat',
  '',
  `Match: ${combat.match.durationSeconds} s, spawn interval ${combat.match.spawnIntervalSeconds} s (the most demanding setting), seed ${combat.match.seed}. ${combat.match.note}`,
  '',
  `Ended by \`${combat.match.endedBy}\` after ${combat.match.elapsedSeconds} s of play; ${combat.match.shotsFired} player shots, ${combat.match.enemiesDestroyed} enemies destroyed.`,
  '',
  '| Metric | Value |',
  '| --- | --- |',
  `| Frames measured | ${combat.frames.count} |`,
  `| Average FPS | **${combat.frames.averageFps}** (target 60) |`,
  `| Mean frame time | ${combat.frames.meanFrameMs} ms |`,
  `| p50 frame time | ${combat.frames.p50FrameMs} ms |`,
  `| **p95 frame time** | **${combat.frames.p95FrameMs} ms** |`,
  `| p99 frame time | ${combat.frames.p99FrameMs} ms |`,
  `| Worst frame | ${combat.frames.maxFrameMs} ms |`,
  `| Frames over 20 ms | ${combat.frames.framesOver20ms} |`,
  '',
  '| Entities | Peak | Mean |',
  '| --- | --- | --- |',
  `| Enemy ships | ${combat.entities.peak.enemies} | ${combat.entities.mean.enemies} |`,
  `| Ship views (incl. player) | ${combat.entities.peak.ships} | ${combat.entities.mean.ships} |`,
  `| Cannonballs | ${combat.entities.peak.projectiles} | ${combat.entities.mean.projectiles} |`,
  `| Active effects | ${combat.entities.peak.effects} | ${combat.entities.mean.effects} |`,
  '',
  'Frame times are measured with `requestAnimationFrame` deltas in the page, independent of the game loop. Entity counts are sampled once per second from the test hooks.',
  '',
  '## Memory after five start / play / leave cycles',
  '',
  memory.procedure,
  '',
  `Baseline (menu, after GC): **${memory.baseline.heapMb} MB** JS heap, ${memory.baseline.windowListeners} listeners on \`window\`, ${memory.baseline.documentListeners} on \`document\`.`,
  '',
  '| Cycle | Heap during match (MB) | Heap after leaving (MB) | `window` listeners | `document` listeners | Canvases left |',
  '| --- | --- | --- | --- | --- | --- |',
  ...memory.cycles.map(
    (cycle) =>
      `| ${cycle.cycle} | ${cycle.heapInMatchMb} | ${cycle.heapAfterLeaveMb} | ${cycle.windowListeners} | ${cycle.documentListeners} | ${cycle.canvases} |`,
  ),
  '',
  `Heap growth between the first and the fifth cycle after leaving: **${memory.growthAfterFirstCycleMb} MB**.`,
  '',
];

const analysisPath = join(dir, 'analysis.md');
const analysis = existsSync(analysisPath) ? `\n${readFileSync(analysisPath, 'utf8')}` : '';
writeFileSync(join(dir, 'README.md'), `${lines.join('\n')}\n${analysis}`);
console.log(lines.join('\n'));
